try{const raw=localStorage.getItem(STORE_KEY);if(raw){const parsed=JSON.parse(raw);const hasRecords=["transactions","accounts","assets","liabilities","budgets"].some(k=>Array.isArray(parsed[k])&&parsed[k].length);if(hasRecords&&!localStorage.getItem("mywealth-preupdate-backup-v1"))localStorage.setItem("mywealth-preupdate-backup-v1",raw);}}catch(e){console.warn("My Wealth safety snapshot skipped",e);}

function emptyState(){return {transactions:[],assets:[],liabilities:[],budgets:[],accounts:[],categories:[],investments:[],investmentTransactions:[],investmentSnapshots:[],netWorthSnapshots:[],reminders:[],bluecoinsMeta:null};}
function loadState(){try{return {...emptyState(),...JSON.parse(localStorage.getItem(STORE_KEY)||"{}")};}catch{return emptyState();}}
// IndexedDB is the primary store. localStorage is retained only as a small legacy
// migration source; the multi-megabyte Bluecoins history is never written there.
const DB_NAME="mywealth-db", DB_VERSION=1, DB_STORE="finance";
let financeDB=null;
function openFinanceDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(DB_STORE))db.createObjectStore(DB_STORE);};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||Error("Could not open IndexedDB"));req.onblocked=()=>reject(Error("Database upgrade is blocked by another open My Wealth tab"));});}
function dbGet(key){return new Promise((resolve,reject)=>{const tx=financeDB.transaction(DB_STORE,"readonly"),req=tx.objectStore(DB_STORE).get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbPut(key,value){return new Promise((resolve,reject)=>{const tx=financeDB.transaction(DB_STORE,"readwrite");tx.objectStore(DB_STORE).put(value,key);tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error||Error("Database write failed"));tx.onabort=()=>reject(tx.error||Error("Database write aborted"));});}
async function initStorage(){
 if(!("indexedDB" in window))throw Error("This browser does not support IndexedDB. Open My Wealth in Safari.");
 financeDB=await openFinanceDB();
 const saved=await dbGet("app-state");
 if(saved&&Array.isArray(saved.transactions)){state={...emptyState(),...saved};}
 else { // One-time migration from the previous localStorage version.
   const legacy=loadState();
   await dbPut("app-state",legacy);
   state=legacy;
 }
 // Legacy Bluecoins repairs are isolated from native My Wealth JSON restores.
 // A restored native backup must survive restart byte-for-byte at the data level:
 // do not re-migrate opening balances or remove its recurring reminders.
 const migration=MyWealthCore.applyLegacyBluecoinsStartupMigrations(state);
 if(migration.corrected>0||migration.migrated>0||migration.removedReminders>0)await dbPut("app-state",state);
 try{localStorage.setItem("mywealth-storage-mode","indexeddb-v1");}catch{}
 return true;
}
const storageReady=initStorage().catch(err=>{console.error("IndexedDB initialization failed",err);toast("Storage could not be initialized: "+err.message);throw err;});
async function persist(){
 try{
   await storageReady;
   for(const tx of (state.transactions||[])){if(tx.sourceRecord!==undefined)delete tx.sourceRecord;}
   recordNetWorthSnapshot();
   // A single atomic IndexedDB transaction prevents partial imports from being reported as saved.
   await dbPut("app-state",state);
   render();return true;
 }catch(err){console.error("My Wealth IndexedDB save failed",err);toast("Save failed. Your data has not been confirmed as saved: "+(err?.message||"storage error"));return false;}
}
function cloneState(){return JSON.parse(JSON.stringify(state));}
