$("investmentTransactionForm").onsubmit=async e=>{e.preventDefault();if(!$("investmentTxHolding").value){toast("Add a holding before recording its transaction");return;}const payload={holdingId:$("investmentTxHolding").value,type:$("investmentTxType").value,toHoldingId:$("investmentTxType").value==="Switch"?$("investmentTxToHolding").value:null,toUnits:Number($("investmentTxToUnits").value)||0,date:$("investmentTxDate").value,amount:Number($("investmentTxAmount").value)||0,units:Number($("investmentTxUnits").value)||0,price:Number($("investmentTxPrice").value)||0,note:$("investmentTxNote").value.trim(),source:"Manual"};if(payload.amount<=0)return;if(payload.type==="Switch"&&(!payload.toHoldingId||payload.toHoldingId===payload.holdingId)){toast("Choose a different destination investment for the switch");return;}const before=cloneState();let t=state.investmentTransactions.find(x=>String(x.id)===String(editingInvestmentTxId));if(t){applyManualInvestmentTx(t,-1);Object.assign(t,payload);applyManualInvestmentTx(t,1);}else{t={id:id(),...payload};state.investmentTransactions.push(t);applyManualInvestmentTx(t,1);}if(!(await persistWithRollback(before)))return;$("investmentTransactionDialog").close();editingInvestmentTxId=null;toast("Investment transaction saved");};
$("deleteInvestmentTxBtn").onclick=async()=>{const t=state.investmentTransactions.find(x=>String(x.id)===String(editingInvestmentTxId));if(!t||!confirm("Delete this investment transaction?"))return;const before=cloneState();applyManualInvestmentTx(t,-1);state.investmentTransactions=state.investmentTransactions.filter(x=>x!==t);if(!(await persistWithRollback(before)))return;$("investmentTransactionDialog").close();editingInvestmentTxId=null;toast("Investment transaction deleted");};
function renderInvestmentTransactions(holdingIds=null,targetId="investmentTransactionsList"){const target=$(targetId),rows=(state.investmentTransactions||[]).filter(t=>!holdingIds||holdingIds.has(String(t.holdingId))||holdingIds.has(String(t.toHoldingId))).sort((a,b)=>String(b.date).localeCompare(String(a.date)));target.innerHTML=`<button class="primary-btn small" id="addInvestmentTxFromList" type="button">＋ Add transaction</button>`+(rows.length?rows.map(t=>`<div class="list-row"><div class="row-main"><strong>${esc(t.name||t.type||"Investment transaction")}</strong><small>${esc(t.date||"")} · ${esc(t.note||t.description||t.account||"")}${t.toHoldingId?" · Switch destination linked":""}</small></div><div class="row-amount">${money(t.amount)}</div><button class="text-btn" data-edit-investment-tx="${esc(t.id)}">Edit</button></div>`).join(""):empty("No investment transactions recorded yet."));target.querySelector("#addInvestmentTxFromList").onclick=()=>openInvestmentTxEditor();target.querySelectorAll("[data-edit-investment-tx]").forEach(b=>b.onclick=()=>openInvestmentTxEditor(b.dataset.editInvestmentTx));}
