let pdfJsPromise=null;
function loadPdfJs(){if(window.pdfjsLib)return Promise.resolve(window.pdfjsLib);if(!pdfJsPromise)pdfJsPromise=new Promise((resolve,reject)=>{const script=document.createElement("script");script.src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";script.onload=()=>window.pdfjsLib?resolve(window.pdfjsLib):(pdfJsPromise=null,reject(Error("PDF.js loaded without its browser API.")));script.onerror=()=>{pdfJsPromise=null;reject(Error("PDF reading library unavailable. Connect to the internet and try again."));};document.head.appendChild(script);});return pdfJsPromise;}
function pdfItemsToText(pdf){return (async()=>{const pages=[];for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p),content=await page.getTextContent(),groups=new Map();for(const item of content.items){if(!item.str?.trim())continue;const y=Math.round(item.transform[5]/1.5)*1.5;const x=item.transform[4];if(!groups.has(y))groups.set(y,[]);groups.get(y).push({x,text:item.str});}const lines=[...groups.entries()].sort((a,b)=>b[0]-a[0]).map(([,items])=>items.sort((a,b)=>a.x-b.x).map(x=>x.text).join(" "));pages.push(lines.join("\n"));}return pages.join("\n\f\n");})();}
async function parseEcasFile(file){if(/\.pdf$/i.test(file.name)||file.type==="application/pdf"){const lib=await loadPdfJs();lib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";const password=$("ecasPassword").value||undefined;let pdf;try{pdf=await lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),password}).promise;}catch(err){if(err?.name==="PasswordException")throw Error(password?"The PDF password was not accepted. Check it and try again.":"This PDF is password-protected. Enter its password above, then try again.");throw err;}const text=await pdfItemsToText(pdf);return MyWealthCore.parseEcasText(text);}throw Error("Choose the original CDSL eCAS PDF. Other file formats are not accepted by this reconciled parser.");}
async function runEcasPreview(file){pendingEcasImport=null;$("confirmEcasImport").disabled=true;if(!file){$("ecasPreview").textContent="No statement selected.";return;}$("ecasPreview").textContent="Reading statement and reconciling holdings…";try{const parsed=await parseEcasFile(file);pendingEcasImport=parsed;const totals=parsed.parsedTotals;$("ecasPreview").innerHTML=`<strong>Statement reconciled ✓</strong><br>${parsed.mutualFunds.length} mutual fund folios · ${parsed.demat.length} demat holdings<br>Mutual funds: ${money(totals["Mutual Funds"])}<br>Stocks: ${money(totals.Stocks)}<br>ETFs: ${money(totals.ETFs)}<br>Others: ${money(totals.Others)}<br><strong>Total: ${money(parsed.summary.total)}</strong><br>${parsed.investmentTransactions.length} investment transactions · ${parsed.historical.length} historical monthly valuations<br>All category and portfolio totals match the statement.`;$("confirmEcasImport").disabled=false;}catch(err){$("ecasPreview").textContent=`Import blocked: ${err.message}`;console.error("eCAS parser",err);}}
$("ecasFile").onchange=e=>{selectedEcasFile=e.target.files?.[0]||null;runEcasPreview(selectedEcasFile);};
$("ecasPassword").addEventListener("change",()=>{if(selectedEcasFile)runEcasPreview(selectedEcasFile);});
$("investmentImportDialog").addEventListener("close",()=>{$("ecasPassword").value="";pendingEcasImport=null;selectedEcasFile=null;$("confirmEcasImport").disabled=true;});
$("investmentImportForm").onsubmit=async e=>{e.preventDefault();if(!pendingEcasImport?.valid)return;const before=cloneState();const result=MyWealthCore.upsertEcasImport(state,pendingEcasImport,id);if(!(await persistWithRollback(before)))return;$("investmentImportDialog").close();$("ecasFile").value="";$("ecasPassword").value="";selectedEcasFile=null;pendingEcasImport=null;$("confirmEcasImport").disabled=true;toast(`eCAS imported: ${result.added} new holdings, ${result.updated} updated, ${result.transactions} transactions`);};

function renderTransferReconciliation(){
 const candidates=MyWealthCore.findHistoricalTransferCandidates(state.transactions,{maxDays:1,minScore:65});
 const target=$("transferCandidateList"),badge=$("transferCandidateBadge");if(badge)badge.textContent=candidates.length?`${candidates.length} candidates`:"No candidates";
 target.innerHTML=candidates.length?candidates.map(c=>`<article class="transfer-candidate-card"><div class="transfer-candidate-top"><strong>${money(c.amount)}</strong><span>${c.score>=85?"Strong candidate":"Possible match"}</span></div><p>${esc(c.expense.account||"Source account")} → ${esc(c.income.account||"Destination account")}</p><small>${esc(String(c.expense.date||"").slice(0,10))} · ${esc(c.expense.note||c.expense.description||c.expense.category||"Expense")} / ${esc(c.income.note||c.income.description||c.income.category||"Income")}</small><p class="hint">${esc(c.reason)} · ${c.daysApart} day(s) apart</p><div class="button-row"><button class="primary-btn" data-confirm-transfer="${esc(c.id)}" type="button">Confirm as self transfer</button><button class="secondary-btn" data-dismiss-transfer="${esc(c.id)}" type="button">Not a transfer</button></div></article>`).join(""):empty("No likely unpaired self transfers found. The scan does not change any transactions.");
 const reconciled=state.transactions.filter(t=>t.kind==="Transfer"&&t.source==="Historical reconciliation");$("reconciledTransferList").innerHTML=reconciled.length?reconciled.map(t=>`<div class="list-row"><div class="row-main"><strong>${money(t.amount)} · ${esc(t.account)} → ${esc(t.counterAccount)}</strong><small>${esc(String(t.date||"").slice(0,10))} · Original entries retained</small></div><button class="text-btn" data-undo-transfer="${esc(t.id)}">Undo</button></div>`).join(""):empty("No historical pairs have been reconciled yet.");
 document.querySelectorAll("[data-confirm-transfer]").forEach(b=>b.onclick=async()=>{const c=candidates.find(x=>x.id===b.dataset.confirmTransfer);if(!c)return;if(!confirm(`Convert the ${money(c.amount)} pair (${c.expense.account} → ${c.income.account}) into one self transfer? Original entries will be retained for undo.`))return;try{const before=cloneState();MyWealthCore.reconcileTransferPair(state,c,id);if(!(await persistWithRollback(before)))return;renderTransferReconciliation();toast("Historical self transfer reconciled");}catch(err){toast(err.message);}});
 document.querySelectorAll("[data-dismiss-transfer]").forEach(b=>b.onclick=async()=>{const c=candidates.find(x=>x.id===b.dataset.dismissTransfer);if(!c)return;const a=state.transactions.find(x=>String(x.id)===String(c.expenseId)),z=state.transactions.find(x=>String(x.id)===String(c.incomeId));const before=cloneState();if(a)a.transferCandidateDismissed=true;if(z)z.transferCandidateDismissed=true;if(!(await persistWithRollback(before)))return;renderTransferReconciliation();});
 document.querySelectorAll("[data-undo-transfer]").forEach(b=>b.onclick=async()=>{if(!confirm("Undo this reconciliation and restore the original income and expense entries?"))return;const before=cloneState();MyWealthCore.undoTransferReconciliation(state,b.dataset.undoTransfer);if(!(await persistWithRollback(before)))return;renderTransferReconciliation();toast("Original transactions restored");});
}
