function categoryIconSvg(t){const c=String(t.category||"").toLowerCase();let p='<path d="M4 12h16M12 4v16"/>';if(/food|dining|restaurant|swiggy|zomato/.test(c))p='<path d="M6 3v8m-3-8v5a3 3 0 0 0 6 0V3M6 11v10m10-18v18m0-18c3 3 3 7 0 10"/>';else if(/grocery|supermarket/.test(c))p='<path d="M3 4h2l2 12h11l3-8H6M9 20h.01M17 20h.01"/>';else if(/fuel|petrol|diesel/.test(c))p='<path d="M5 21V4a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v17M4 21h13M8 6h5v5H8zM16 8h2l2 3v6a2 2 0 0 1-4 0v-4"/>';else if(/wifi|internet|subscription/.test(c))p='<path d="M2 8a15 15 0 0 1 20 0M5 12a10 10 0 0 1 14 0m-11 4a5 5 0 0 1 8 0m-4 4h.01"/>';else if(t.kind==="Transfer")p='<path d="M3 8h17m-4-4 4 4-4 4M21 16H4m4-4-4 4 4 4"/>';else if(t.kind==="Income")p='<path d="M12 19V5m-6 6 6-6 6 6"/>';else p='<path d="M12 5v14m-6-6 6 6 6-6"/>';return `<svg viewBox="0 0 24 24" aria-hidden="true">${p}</svg>`;}
function transactionBalanceAfter(t){const account=state.accounts.find(a=>String(a.id)===String(t.accountId));if(!account)return null;const list=(state.transactions||[]).filter(x=>!x.isReminder&&!x.isTransferReconciled&&Number(x.deletedFlag)!==5&&String(x.date||"")<=String(t.date||"")).sort((a,b)=>String(a.date||"").localeCompare(String(b.date||""))||(state.transactions.indexOf(b)-state.transactions.indexOf(a)));let bal=Number(account.openingBalance)||0;for(const x of list){if(String(x.accountId)===String(account.id)){const amt=Math.abs(Number(x.amount)||0);if(x.source==="Bluecoins"&&x.sourceAmountRaw!==undefined&&Number(x.sourceAmountRaw)!==0)bal+=Math.sign(Number(x.sourceAmountRaw))*amt;else if(x.kind==="Transfer"||x.kind==="Expense")bal-=amt;else if(x.kind==="Income")bal+=amt;}else if(x.kind==="Transfer"&&x.source!=="Bluecoins"&&String(x.counterAccountId)===String(account.id))bal+=Math.abs(Number(x.amount)||0);if(String(x.id)===String(t.id))return bal;}return null;}
function txRow(t,actions=false){const color=t.kind==="Income"?"positive":t.kind==="Expense"?"negative":"";const balance=transactionBalanceAfter(t);return `<div class="list-row transaction-row" data-open-tx="${esc(t.id)}">${actions?`<label class="tx-select"><input type="checkbox" data-select-tx="${esc(t.id)}" ${selectedTransactionIds.has(String(t.id))?"checked":""} aria-label="Select transaction"></label>`:""}<div class="row-icon ${t.kind==="Income"?"income-icon":t.kind==="Expense"?"expense-icon":"transfer-icon"}">${categoryIconSvg(t)}</div><div class="row-main"><strong>${esc(t.category)}</strong><small>${esc(t.note||t.kind)}${t.account?" · "+esc(t.account):""}${t.recurring?" · Recurring":""}</small></div><div class="tx-amount-stack"><div class="row-amount ${color}">${t.kind==="Income"?"+":t.kind==="Expense"?"−":""}${money(t.amount)}</div>${balance===null?"":`<small class="tx-account-balance">Balance ${money(balance)}</small>`}</div></div>`;}

function bindDeletes(){document.querySelectorAll("[data-delete]").forEach(b=>b.onclick=async()=>{const key={transaction:"transactions",asset:"assets",debt:"liabilities"}[b.dataset.delete];if(!confirm("Delete this record?"))return;state[key]=state[key].filter(x=>x.id!==b.dataset.id);await persist();});}
function budgetCategoryIcon(category){const c=String(category||"").toLowerCase();let path='<circle cx="12" cy="12" r="7"/><path d="M12 8v8m-4-4h8"/>';if(/food|dining|restaurant/.test(c))path='<path d="M6 3v8m-3-8v5a3 3 0 0 0 6 0V3M6 11v10m10-18v18m0-18c3 3 3 7 0 10"/>';else if(/grocer|supermarket/.test(c))path='<path d="M3 4h2l2 12h11l3-8H6M9 20h.01M17 20h.01"/>';else if(/transport|travel|fuel/.test(c))path='<path d="M5 18V6a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v12M3 18h18M8 8h8v5H8zM8 21h.01M16 21h.01"/>';else if(/utilit|electric|water|bill/.test(c))path='<path d="M13 2 5 13h6l-1 9 9-12h-6z"/>';else if(/subscription|internet/.test(c))path='<path d="M2 8a15 15 0 0 1 20 0M5 12a10 10 0 0 1 14 0m-11 4a5 5 0 0 1 8 0m-4 4h.01"/>';else if(/housing|home|rent/.test(c))path='<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>';return `<svg viewBox="0 0 24 24" aria-hidden="true">${path}</svg>`;}

function renderBudgetEditor(){
 const categories=[...new Set([...getCategories("Expense"),...(state.budgets||[]).map(b=>b.category)])].filter(Boolean).sort((a,b)=>a.localeCompare(b));
 const current=new Map((state.budgets||[]).map(b=>[b.category,Number(b.limit)||0]));
 const host=$("budgetEditList");if(!host)return;
 host.innerHTML=categories.map(category=>`<label class="budget-edit-row"><span class="budget-category-icon">${budgetCategoryIcon(category)}</span><strong>${esc(category)}</strong><span class="budget-edit-input-wrap"><span>₹</span><input type="number" min="0" step="0.01" inputmode="decimal" data-budget-edit="${esc(category)}" value="${current.get(category)||""}" placeholder="0"></span></label>`).join("");
}
$("saveAllBudgetsBtn").onclick=async()=>{const before=cloneState(),existing=new Map((state.budgets||[]).map(b=>[b.category,b]));const next=[];document.querySelectorAll("[data-budget-edit]").forEach(input=>{const limit=Number(input.value);if(Number.isFinite(limit)&&limit>0){const prior=existing.get(input.dataset.budgetEdit);next.push({id:prior?.id||id(),category:input.dataset.budgetEdit,limit});}});state.budgets=next;if(!(await persistWithRollback(before)))return;toast("Budgets saved");nav("budgets");};
if($("budgetEditMonth"))$("budgetEditMonth").addEventListener("change",()=>{$("budgetMonth").value=$("budgetEditMonth").value;render();});
function renderBudgets(){const month=$("budgetMonth").value||monthKey();const monthExpenses=state.transactions.filter(t=>t.kind==="Expense"&&inMonth(t.date,month));const spentTotal=sum(monthExpenses,t=>t.amount);const budgetTotal=sum(state.budgets,b=>Number(b.limit)||0);const pctTotal=budgetTotal?Math.min(100,spentTotal/budgetTotal*100):0;$("budgetGaugeSpent").textContent=money(spentTotal);$("budgetGaugeLimit").textContent=`of ${money(budgetTotal)}`;$("budgetGaugePercent").textContent=`${Math.round(pctTotal)}% spent`;
$("budgetGaugeRemaining").textContent=`${money(budgetTotal-spentTotal)} remaining`;$("budgetGaugeFill").style.strokeDasharray=`${Math.PI*96}`;$("budgetGaugeFill").style.strokeDashoffset=`${Math.PI*96*(1-pctTotal/100)}`;
$("budgetList").className="budget-stack"+ (state.budgets.length?"":" empty");
$("budgetList").innerHTML=state.budgets.length?state.budgets.map(b=>{const spent=sum(state.transactions.filter(t=>!t.isTransferReconciled&&t.kind==="Expense"&&t.category===b.category&&inMonth(t.date,month)),t=>t.amount),pct=b.limit?spent/b.limit*100:0;return `<button type="button" class="budget-item budget-category-row" data-budget-category="${esc(b.category)}"><span class="budget-category-icon">${budgetCategoryIcon(b.category)}</span><span class="budget-category-main"><span class="budget-category-line"><strong>${esc(b.category)}</strong><span>${money(spent)} <i>/ ${money(b.limit)}</i></span></span><span class="budget-progress-line"><span class="progress"><span class="${pct>100?"over":""}" style="width:${Math.min(100,pct)}%"></span></span><b>${Math.round(pct)}%</b></span></span></button>`;}).join(""):empty("No budgets set yet.");
}

const REPORT_PALETTE=["#d95f59","#e7a52b","#2c9a68","#4b91bd","#8c79cf","#d47d43","#65a7a0","#a5b45b","#c16c9a","#7f8b96"];
let activeReportView="spending";
function reportRows(kind){
 const from=$("reportFrom")?.value||monthKey()+"-01",to=$("reportTo")?.value||new Date().toISOString().slice(0,10),account=$("reportAccount")?.value||"",category=$("reportCategory")?.value||"";
 return state.transactions.filter(t=>!t.isReminder&&!t.isTransferReconciled&&t.kind===kind&&String(t.date||"")>=from&&String(t.date||"")<=to&&(!account||String(t.accountId)===String(account))&&(!category||t.category===category));
}
function reportPieMarkup(rows,kind){
 const sums={};rows.forEach(t=>sums[t.category||"Uncategorised"]=(sums[t.category||"Uncategorised"]||0)+Number(t.amount||0));
 const entries=Object.entries(sums).sort((a,b)=>b[1]-a[1]),total=entries.reduce((a,x)=>a+x[1],0);
 let acc=0;const stops=entries.map(([name,value],i)=>{const from=total?acc/total*100:0;acc+=value;const to=total?acc/total*100:0;return `${REPORT_PALETTE[i%REPORT_PALETTE.length]} ${from}% ${to}%`;});
 const donut=kind==="Expense"?$("spendingDonut"):$("incomeDonut"),legend=kind==="Expense"?$("spendingLegend"):$("incomeLegend"),totalEl=kind==="Expense"?$("spendingDonutTotal"):$("incomeDonutTotal");
 if(donut)donut.style.background=entries.length?`conic-gradient(${stops.join(",")})`:"conic-gradient(#dfe8e2 0% 100%)";
 if(totalEl)totalEl.textContent=money(total);
 if(legend)legend.innerHTML=entries.length?entries.map(([name,value],i)=>`<div class="report-legend-row"><i style="background:${REPORT_PALETTE[i%REPORT_PALETTE.length]}"></i><span>${esc(name)}</span><b>${total?((value/total)*100).toFixed(1):"0.0"}%</b></div>`).join(""):empty(`No ${kind.toLowerCase()} data`);
 return {entries,total};
}
function reportCategoryIcon(category,kind){return categoryIconSvg({category,kind});}
function renderReportCategoryRows(rows,kind,total){
 const target=kind==="Expense"?$("categoryReport"):$("reportIncomeSummary");
 const grouped={};rows.forEach(t=>{const key=t.category||"Uncategorised";grouped[key]=(grouped[key]||0)+Number(t.amount||0);});
 const entries=Object.entries(grouped).sort((a,b)=>b[1]-a[1]);
 target.className="report-category-list"+(entries.length?"":" empty");
 target.innerHTML=entries.length?entries.map(([c,v],i)=>`<button type="button" class="report-category-item" data-report-category="${esc(c)}" data-report-kind="${kind}"><span class="report-category-icon ${kind==="Income"?"income-icon":"expense-icon"}">${reportCategoryIcon(c,kind)}</span><span class="report-category-main"><strong>${esc(c)}</strong><small>${money(v)} · ${total?Math.round(v/total*100):0}%</small><i class="report-category-progress"><b style="width:${total?Math.max(1,v/total*100):0}%;background:${REPORT_PALETTE[i%REPORT_PALETTE.length]}"></b></i></span><b class="report-category-percent">${total?Math.round(v/total*100):0}%</b><span class="report-category-chevron">›</span></button>`).join(""):empty(`No ${kind.toLowerCase()} data for this period.`);
}
function calculateCurrentNetWorth(){
 const assets=sum(state.assets||[],x=>Number(x.value)||0)+sum((state.accounts||[]).filter(a=>!a.closed),accountBalance)+sum(state.investments||[],x=>Number(x.value)||0);
 const liabilities=sum(state.liabilities||[],x=>Number(x.value)||0);
 return {assets,liabilities,net:assets-liabilities};
}
function recordNetWorthSnapshot(){
 const current=calculateCurrentNetWorth(),now=new Date(),date=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}-${String(now.getDate()).padStart(2,"0")}`;
 state.netWorthSnapshots=Array.isArray(state.netWorthSnapshots)?state.netWorthSnapshots:[];
 const found=state.netWorthSnapshots.find(x=>x.date===date);
 if(found){found.assets=current.assets;found.liabilities=current.liabilities;found.net=current.net;}
 else state.netWorthSnapshots.push({date,...current});
 state.netWorthSnapshots=state.netWorthSnapshots.slice(-730);
}
function renderNetWorthReport(){
 const n=calculateCurrentNetWorth(),value=$("reportNetWorthValue");
 if(value)value.textContent=money(n.net);
 const snapshots=[...(state.netWorthSnapshots||[])].sort((a,b)=>String(a.date).localeCompare(String(b.date)));
 const chart=$("netWorthTrendChart");
 if(chart){
  if(snapshots.length<2){chart.innerHTML=`<div class="report-chart-empty"><strong>${money(n.net)}</strong><span>Net worth tracking starts now. Your trend will build as snapshots are recorded over time.</span></div>`;}
  else{
   const w=320,h=150,pad=18,vals=snapshots.map(x=>Number(x.net)||0),min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;
   const pts=vals.map((v,i)=>`${pad+i/(vals.length-1)*(w-pad*2)},${h-pad-(v-min)/range*(h-pad*2)}`).join(" ");
   const area=`${pad},${h-pad} ${pts} ${w-pad},${h-pad}`;
   chart.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Net worth trend"><defs><linearGradient id="nwAreaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#19835e" stop-opacity=".28"/><stop offset="1" stop-color="#19835e" stop-opacity=".02"/></linearGradient></defs><polygon points="${area}" fill="url(#nwAreaFill)"/><polyline points="${pts}" fill="none" stroke="#16845e" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${snapshots.map((x,i)=>{const [cx,cy]=pts.split(" ")[i].split(",");return `<circle cx="${cx}" cy="${cy}" r="3" fill="#16845e"><title>${esc(x.date)} · ${money(x.net)}</title></circle>`;}).join("")}</svg><div class="report-chart-axis"><span>${esc(snapshots[0].date)}</span><span>${esc(snapshots[snapshots.length-1].date)}</span></div>`;
  }
 }
 const breakdown=$("netWorthBreakdown");
 if(breakdown)breakdown.innerHTML=[
  ["Assets",n.assets,"positive","Accounts, assets and investments"],
  ["Liabilities",n.liabilities,"negative","Outstanding balances"],
  ["Net Worth",n.net,"","Assets minus liabilities"]
 ].map(([label,v,cls,desc])=>`<div class="report-breakdown-row"><span class="report-breakdown-icon">${label==="Assets"?"▱":label==="Liabilities"?"▣":"◈"}</span><span><strong>${label}</strong><small>${desc}</small></span><b class="${cls}">${money(v)}</b></div>`).join("");
 const change=$("reportNetWorthChange");if(change)change.textContent=snapshots.length>1?`${snapshots.length} recorded snapshots`:"Current value · history starts now";
}
function setReportView(view){
 activeReportView=view;
 document.querySelectorAll("[data-report-view]").forEach(b=>b.classList.toggle("selected",b.dataset.reportView===view));
 ["spending","income","networth"].forEach(v=>{const el=$("report"+(v==="networth"?"NetWorth":v[0].toUpperCase()+v.slice(1))+"View");if(el)el.hidden=v!==view;});
}
document.querySelectorAll("[data-report-view]").forEach(b=>b.addEventListener("click",()=>setReportView(b.dataset.reportView)));
function renderReports(){
 const expenseRows=reportRows("Expense"),incomeRows=reportRows("Income");
 const expenseTotal=sum(expenseRows,t=>Number(t.amount)||0),incomeTotal=sum(incomeRows,t=>Number(t.amount)||0);
 $("reportExpense").textContent=money(expenseTotal);$("reportIncome").textContent=money(incomeTotal);
 $("reportSpendingPeriod").textContent=$("reportFrom").value&&$("reportTo").value?`${$("reportFrom").value} – ${$("reportTo").value}`:"All recorded dates";
 $("reportIncomePeriod").textContent=$("reportSpendingPeriod").textContent;
 reportPieMarkup(expenseRows,"Expense");reportPieMarkup(incomeRows,"Income");
 renderReportCategoryRows(expenseRows,"Expense",expenseTotal);renderReportCategoryRows(incomeRows,"Income",incomeTotal);
 renderNetWorthReport();setReportView(activeReportView);
}
function openReportCategory(category,kind="Expense"){
 const rows=reportRows(kind).filter(t=>(t.category||"Uncategorised")===category).sort((a,b)=>String(b.date).localeCompare(String(a.date)));
 const total=sum(rows,t=>Number(t.amount)||0);
 $("reportCategoryTitle").textContent=category;
 $("reportCategorySubtitle").textContent=kind==="Income"?"Income transactions":"Expense transactions";
 $("reportCategoryTotal").textContent=money(total);
 $("reportCategoryCount").textContent=`${rows.length} transactions`;
 const budgetMeta=$("reportCategoryBudgetMeta"),from=$("reportFrom").value||monthKey()+"-01",to=$("reportTo").value||new Date().toISOString().slice(0,10),budget=kind==="Expense"&&from.slice(0,7)===to.slice(0,7)?(state.budgets||[]).find(b=>b.category===category):null;
 if(budgetMeta){const pct=budget&&Number(budget.limit)>0?total/Number(budget.limit)*100:null;budgetMeta.textContent=budget?`of ${money(budget.limit)} budget · ${Math.round(pct)}% used`:"";}
 const list=$("reportCategoryTransactions");
 if(!rows.length)list.innerHTML=empty("No transactions in this category for the selected period.");
 else{
  const byDate={};rows.forEach(t=>(byDate[t.date||"Undated"] ||= []).push(t));
  list.innerHTML=Object.entries(byDate).sort((a,b)=>b[0].localeCompare(a[0])).map(([date,items])=>`<div class="report-date-heading">${esc(date)}</div>${items.map(t=>txRow(t,false)).join("")}`).join("");
 }
 $("reportMainView").hidden=true;$("reportCategoryDetailView").hidden=false;if($("topFilterBtn"))$("topFilterBtn").hidden=true;
 $("reports").scrollTo(0,0);document.querySelector("main")?.scrollTo(0,0);
}

function getCategories(kind){
 const base=kind==="Income"?INCOMES:EXPENSES;
 const raw=state.categories;
 // Bluecoins migration stores category metadata as {parents:[], children:[]};
 // user-managed categories use an array. Never call .filter on the object shape.
 const rows=Array.isArray(raw)?raw:[];
 const hidden=new Set(rows.filter(c=>c.kind===kind&&(c.deleted||c.oldName)).map(c=>c.oldName||c.name));
 const renamed=rows.filter(c=>c.kind===kind&&c.oldName&&!c.deleted).map(c=>c.name);
 const custom=rows.filter(c=>c.kind===kind&&!c.deleted&&!c.oldName).map(c=>c.name);
 const imported=(state.transactions||[]).filter(t=>t.kind===kind&&t.category&&!t.isReminder).map(t=>t.category);
 return [...new Set([...base.filter(n=>!hidden.has(n)),...renamed,...custom,...imported])].filter(Boolean).sort((a,b)=>a.localeCompare(b));
}
$("manageCategoriesBtn").onclick=()=>{renderCategoryManager();showDialog("categoryDialog");};
function renderCategoryManager(){if(!Array.isArray(state.categories))state.categories=[];const kind=$("categoryKind").value;$("categoryListEditor").innerHTML=[...getCategories(kind)].map(n=>`<div class="category-edit-row"><span>${esc(n)}</span><button type="button" class="text-btn" data-category-edit="${esc(n)}">Rename</button><button type="button" class="text-btn" data-category-delete="${esc(n)}">Delete</button></div>`).join("");document.querySelectorAll("[data-category-edit]").forEach(b=>b.onclick=async()=>{const old=b.dataset.categoryEdit,n=prompt("New category name",old);if(!n||!n.trim())return;const c=state.categories.find(x=>x.kind===kind&&x.name===old);if(c)c.name=n.trim();else state.categories.push({kind,name:n.trim(),oldName:old});state.transactions.forEach(t=>{if(t.kind===kind&&t.category===old)t.category=n.trim();});await persist();renderCategoryManager();});document.querySelectorAll("[data-category-delete]").forEach(b=>b.onclick=async()=>{const name=b.dataset.categoryDelete;if(!confirm(`Remove ${name} from category choices? Existing transactions will keep this category.`))return;state.categories.push({kind,name,deleted:true});await persist();renderCategoryManager();});}
$("categoryKind").onchange=renderCategoryManager;
$("categoryForm").onsubmit=async e=>{e.preventDefault();const kind=$("categoryKind").value,name=$("categoryName").value.trim();if(!name)return;if(getCategories(kind).some(x=>x.toLowerCase()===name.toLowerCase())){toast("Category already exists");return;}state.categories.push({kind,name});if(!(await persist()))return;$("categoryName").value="";renderCategoryManager();toast("Category added");};
$("bluecoinsInput").onchange=async e=>{pendingBluecoins=null;$("confirmBluecoinsBtn").disabled=true;const file=e.target.files?.[0];if(!file){$("bluecoinsPreview").textContent="No Bluecoins file selected.";return;}try{const obj=JSON.parse(await file.text());if(!Array.isArray(obj.transactions)||!Array.isArray(obj.accounts))throw Error("The JSON must contain Bluecoins accounts and transactions.");const known=new Set(state.transactions.filter(t=>t.source==="Bluecoins"&&t.sourceId!==undefined).map(t=>String(t.sourceId)));for(const a of (state.accounts||[]))for(const sid of (a.bluecoinsOpeningBalanceSourceIds||[]))known.add(String(sid));const duplicates=obj.transactions.filter(t=>known.has(String(t.sourceId??t.source?.transactionsTableID))).length;pendingBluecoins=obj;$("bluecoinsPreview").textContent=`Ready to import ${obj.transactions.length.toLocaleString("en-IN")} source transactions and ${obj.accounts.length} accounts. ${duplicates.toLocaleString("en-IN")} transactions already exist and will be skipped. Bluecoins signed source amounts are preserved for accurate account balances; duplicate source IDs are skipped. Original source flags, reminders and transfer links are retained.`;$("confirmBluecoinsBtn").disabled=false;}catch(err){$("bluecoinsPreview").textContent="Import preview failed: "+err.message;}};
$("confirmBluecoinsBtn").onclick=async()=>{if(!pendingBluecoins)return;if(!confirm("Import Bluecoins records? Existing records are retained and matching source IDs are skipped."))return;try{const before=cloneState();const result=MyWealthCore.upsertBluecoinsImport(state,pendingBluecoins,id);if(!(await persistWithRollback(before)))return;pendingBluecoins=null;$("bluecoinsInput").value="";$("confirmBluecoinsBtn").disabled=true;$("bluecoinsPreview").textContent=`Import complete: ${result.transactionsAdded} transactions, ${result.openingBalancesImported||0} opening balances, ${result.accountsAdded} accounts added, ${result.duplicates} duplicates skipped.`;toast("Bluecoins history imported safely");}catch(err){toast("Bluecoins import failed: "+err.message);}};



function openTransactionDetail(txid){const t=state.transactions.find(x=>String(x.id)===String(txid));if(!t)return;activeDetailTransactionId=t.id;$("detailTitle").textContent=t.category||t.kind;$("transactionDetailBody").innerHTML=`<div class="detail-grid"><p><small>Date</small><strong>${esc(t.date||"—")}</strong></p><p><small>Amount</small><strong>${money(t.amount)}</strong></p><p><small>Type</small><strong>${esc(t.kind)}</strong></p><p><small>Account</small><strong>${esc(t.account||"Unassigned")}${t.kind==="Transfer"?" → "+esc(t.counterAccount||"Unassigned"):""}</strong></p><p><small>Category</small><strong>${esc(t.category||"—")}</strong></p><p><small>Description</small><strong>${esc(t.note||"—")}</strong></p></div>`;showDialog("transactionDetailDialog");}
function editOrCopyTransaction(copy=false){const t=state.transactions.find(x=>String(x.id)===String(activeDetailTransactionId));if(!t)return;editingTransactionId=copy?null:t.id;currentKind=t.kind==="Income"?"Income":t.kind==="Transfer"?"Transfer":"Expense";$("entryTitle").textContent=copy?"Copy transaction":"Edit transaction";$("saveEntryBtn").textContent=copy?"Save copy":"Save changes";$("transactionForm").reset();$("entryAmount").value=t.amount;$("entryDate").value=copy?new Date().toISOString().slice(0,10):t.date;options($("entryCategory"),getCategories(currentKind),t.category);$("entryNote").value=t.note||"";refreshAccountSelect();$("entryAccount").value=t.accountId||"";$("entryRecurring").checked=!!t.recurring;setTransactionKind(currentKind);$("entryToAccount").value=t.counterAccountId||"";$("transactionDetailDialog").close();showDialog("entryDialog");}
$("detailEditBtn").onclick=()=>editOrCopyTransaction(false);$("detailCopyBtn").onclick=()=>editOrCopyTransaction(true);$("detailDeleteBtn").onclick=async()=>{if(!activeDetailTransactionId||!confirm("Delete this transaction?"))return;state.transactions=state.transactions.filter(t=>String(t.id)!==String(activeDetailTransactionId));$("transactionDetailDialog").close();await persist();toast("Transaction deleted");};
