function openReportCategory(category){const from=$("reportFrom").value||monthKey()+"-01",to=$("reportTo").value||new Date().toISOString().slice(0,10),account=$("reportAccount").value||"";const rows=state.transactions.filter(t=>!t.isReminder&&!t.isTransferReconciled&&t.kind==="Expense"&&t.category===category&&String(t.date)>=from&&String(t.date)<=to&&(!account||String(t.accountId)===String(account))).sort((a,b)=>String(b.date).localeCompare(String(a.date)));$("budgetTransactionsTitle").textContent=`${category} · Expenses · ${from} to ${to}`;$("budgetTransactionsList").innerHTML=`<div class="summary-strip"><span>${rows.length} transactions · Total spending</span><strong>${money(sum(rows,t=>t.amount))}</strong></div>`+(rows.length?rows.map(t=>txRow(t,false)).join(""):empty("No transactions in this category for the selected period."));showDialog("budgetTransactionsDialog");}
