$("restoreJsonInput").onchange=async e=>{const before=cloneState();try{const file=e.target.files?.[0];if(!file) return;const obj=JSON.parse(await file.text());if(!obj||typeof obj!=="object"||!Array.isArray(obj.transactions))throw Error("Invalid My Wealth backup: transactions are missing");if(!confirm("Replace all current local data with this backup?"))return;const restored={...emptyState(),...obj};for(const key of ["assets","liabilities","budgets","accounts","categories","investments","investmentTransactions","investmentSnapshots","netWorthSnapshots","reminders"])if(!Array.isArray(restored[key]))restored[key]=[];restored.myWealthRestore={source:"json",version:1,restoredAt:new Date().toISOString()};state=restored;if(!(await persistWithRollback(before)))throw Error("Could not save restored backup; previous data was retained");toast("My Wealth backup restored successfully");}catch(err){state=before;render();toast("Restore failed: "+err.message);}e.target.value="";};
// CSV and Excel import helpers. Excel support is loaded only when an .xls/.xlsx file is selected.
let sheetJsPromise=null;
function loadSheetJS(){if(window.XLSX)return Promise.resolve(window.XLSX);if(!sheetJsPromise)sheetJsPromise=new Promise((resolve,reject)=>{const sc=document.createElement("script");sc.src="https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js";sc.onload=()=>window.XLSX?resolve(window.XLSX):reject(Error("Excel reader could not be loaded"));sc.onerror=()=>reject(Error("Could not load Excel support. Check your internet connection and try again."));document.head.appendChild(sc);});return sheetJsPromise;}
async function readTabularFile(file){if(!file)throw Error("Choose a file first");const ext=(file.name.split(".").pop()||"").toLowerCase();if(ext==="csv"||file.type.includes("csv")){const rows=parseCSV(await file.text());if(rows.length<2)throw Error("No data rows found");const headers=rows[0].map(x=>String(x).trim());return rows.slice(1).filter(r=>r.some(v=>String(v??"").trim())).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??""])));}if(["xlsx","xls"].includes(ext)){const XLSX=await loadSheetJS(),wb=XLSX.read(await file.arrayBuffer(),{type:"array",cellDates:true});const first=wb.SheetNames[0];if(!first)throw Error("Workbook has no worksheets");const data=XLSX.utils.sheet_to_json(wb.Sheets[first],{defval:"",raw:false});if(!data.length)throw Error("The first worksheet has no data rows");return data;}throw Error("Choose a CSV or Excel (.xlsx/.xls) file");}
function normKey(k){return String(k??"").toLowerCase().replace(/[^a-z0-9]/g,"");}
function pick(row,names){const map=new Map(Object.entries(row).map(([k,v])=>[normKey(k),v]));for(const n of names){const v=map.get(normKey(n));if(v!==undefined&&String(v).trim()!=="")return v;}return "";}
function numeric(v){if(typeof v==="number")return v;const n=Number(String(v??"").replace(/[₹,\s]/g,""));return Number.isFinite(n)?n:NaN;}
function normalizeDate(v){if(v instanceof Date&&!isNaN(v))return v.toISOString().slice(0,10);const s=String(v??"").trim();if(/^\d{4}-\d{2}-\d{2}/.test(s))return s.slice(0,10);const m=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})$/);if(m)return `${m[3].length===2?"20":""}${m[3]}-${m[2].padStart(2,"0")}-${m[1].padStart(2,"0")}`;const d=new Date(s);return isNaN(d)?new Date().toISOString().slice(0,10):d.toISOString().slice(0,10);}
function transactionKey(t){return [t.date,t.kind,Number(t.amount).toFixed(2),String(t.note||"").trim().toLowerCase(),String(t.category||"").trim().toLowerCase(),String(t.accountId||"")].join("|");}
$("importCsvInput").onchange=async e=>{pendingTransactionRows=null;const preview=$("transactionImportPreview"),confirmBtn=$("confirmTransactionImportBtn");preview.hidden=false;confirmBtn.hidden=false;confirmBtn.disabled=true;try{const rows=await readTabularFile(e.target.files?.[0]);const parsed=[];for(const r of rows){let amount=numeric(pick(r,["amount","value","debit/credit","transaction amount"]));const debit=numeric(pick(r,["debit","withdrawal","withdrawals"])),credit=numeric(pick(r,["credit","deposit","deposits"]));if(!Number.isFinite(amount)||amount===0){if(Number.isFinite(credit)&&credit>0)amount=credit;else if(Number.isFinite(debit)&&debit>0)amount=-debit;}if(!Number.isFinite(amount)||amount===0)continue;const raw=String(pick(r,["type","transaction type","kind"])).toLowerCase();let kind=raw.includes("transfer")?"Transfer":raw.includes("income")||raw.includes("credit")||(!raw&&amount>0)?"Income":raw.includes("expense")||raw.includes("debit")||(!raw&&amount<0)?"Expense":amount>0?"Income":"Expense";const accountRef=String(pick(r,["account id","accountid","account","account name","bank account"] )||"").trim();const matchedAccount=state.accounts.find(a=>String(a.id)===accountRef||String(a.name||"").toLowerCase()===accountRef.toLowerCase());parsed.push({id:id(),date:normalizeDate(pick(r,["date","transaction date","txn date","value date"])),amount:Math.abs(amount),kind,category:String(pick(r,["category","head"] )||"Imported"),note:String(pick(r,["description","narration","note","particulars","merchant","details"] )||""),accountId:matchedAccount?.id||"",account:matchedAccount?.name||accountRef,recurring:false,source:"CSV/Excel"});}if(!parsed.length)throw Error("No valid transaction rows. Required columns: date, amount and type (or debit/credit sign).");const existing=new Set((state.transactions||[]).map(transactionKey));const fresh=parsed.filter(t=>{const k=transactionKey(t);if(existing.has(k))return false;existing.add(k);return true;});pendingTransactionRows=fresh;preview.textContent=`Preview: ${parsed.length} valid rows · ${fresh.length} new · ${parsed.length-fresh.length} possible duplicates skipped. First worksheet / CSV data only.`;confirmBtn.disabled=!fresh.length;}catch(err){preview.textContent="Import preview failed: "+err.message;pendingTransactionRows=null;}e.target.value="";};
$("confirmTransactionImportBtn").onclick=async()=>{if(!pendingTransactionRows?.length)return;const before=cloneState();state.transactions.push(...pendingTransactionRows);if(!(await persistWithRollback(before)))return;const n=pendingTransactionRows.length;pendingTransactionRows=null;$("transactionImportPreview").hidden=true;$("confirmTransactionImportBtn").hidden=true;toast(`Imported ${n} transactions`);};
$("wealthFileInput").onchange=async e=>{pendingWealthRows=null;const preview=$("wealthImportPreview"),confirmBtn=$("confirmWealthImportBtn");preview.hidden=false;confirmBtn.hidden=false;confirmBtn.disabled=true;try{const rows=await readTabularFile(e.target.files?.[0]);const parsed=[];for(const r of rows){const name=String(pick(r,["name","holding","security","scheme","instrument","asset name"] )||"").trim(),value=numeric(pick(r,["current value","market value","valuation","value","amount"]));if(!name||!Number.isFinite(value)||value<0)continue;let category=String(pick(r,["category","asset category","type"] )||"").toLowerCase();category=category.includes("mutual")||category==="mf"?"Mutual Funds":category.includes("etf")?"ETFs":category.includes("stock")||category.includes("equity")||category.includes("share")?"Stocks":category.includes("other")||category.includes("deposit")||category.includes("fixed")||category.includes("bond")?"Others":"Others";const assetType=String(pick(r,["subcategory","asset type","instrument type"] )||"");parsed.push({id:id(),category,assetType:assetType||undefined,name,isin:String(pick(r,["isin","security code"] )||""),folio:String(pick(r,["folio","account","demat account"] )||""),units:numeric(pick(r,["units","quantity","qty"])),cost:Number.isFinite(numeric(pick(r,["invested amount","cost","cost value","purchase value"])))?numeric(pick(r,["invested amount","cost","cost value","purchase value"])):null,value});}if(!parsed.length)throw Error("No valid holdings. Required columns: name and current value; category, units, invested amount and ISIN are optional.");const keys=new Set((state.investments||[]).map(h=>(h.isin||h.name||"").toLowerCase()+"|"+h.category));const fresh=parsed.filter(h=>{const k=(h.isin||h.name||"").toLowerCase()+"|"+h.category;if(keys.has(k))return false;keys.add(k);return true;});pendingWealthRows=fresh;preview.textContent=`Preview: ${parsed.length} holdings · ${fresh.length} new · ${parsed.length-fresh.length} matching existing holdings skipped. Values are treated as current market values.`;confirmBtn.disabled=!fresh.length;}catch(err){preview.textContent="Holdings preview failed: "+err.message;pendingWealthRows=null;}e.target.value="";};
$("confirmWealthImportBtn").onclick=async()=>{if(!pendingWealthRows?.length)return;const before=cloneState();state.investments.push(...pendingWealthRows);if(!(await persistWithRollback(before)))return;const n=pendingWealthRows.length;pendingWealthRows=null;$("wealthImportPreview").hidden=true;$("confirmWealthImportBtn").hidden=true;toast(`Imported ${n} holdings`);};
function parseCSV(text){const rows=[];let row=[],cell="",quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"'){quoted=!quoted;}else if(c===","&&!quoted){row.push(cell);cell="";}else if((c==="\n"||c==="\r")&&!quoted){if(c==="\r"&&text[i+1]==="\n")i++;row.push(cell);if(row.some(x=>x!==""))rows.push(row);row=[];cell="";}else cell+=c;}row.push(cell);if(row.some(x=>x!==""))rows.push(row);return rows;}

